import java.util.Scanner;

public class Main {
    static long[] fact = new long[501];
    static long[] invFact = new long[501];
    static long[] fArr = new long[501];
    static long[] gArr = new long[501];
    static long[][][] hArr = new long[501][501][2];
    static long[][] CArr = new long[501][501];
    static long sumS, answerVal, tempF;
    static int nVal, mVal, modVal, invMod;

    static long power(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % modVal;
            base = base * base % modVal;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        nVal = sc.nextInt();
        mVal = sc.nextInt();
        modVal = sc.nextInt();
        invMod = modVal - 2;

        fact[0] = 1;
        for (int i = 1; i <= nVal; i++) {
            fact[i] = fact[i - 1] * i % modVal;
        }

        invFact[nVal] = power(fact[nVal], invMod);
        for (int i = nVal - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % modVal;
        }

        CArr[0][0] = 1;
        for (int i = 1; i <= nVal; i++) {
            CArr[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                CArr[i][j] = (CArr[i - 1][j - 1] + CArr[i - 1][j]) % modVal;
            }
        }

        fArr[0] = 1;
        gArr[0] = 0;
        for (int i = 1; i <= mVal; i++) {
            for (int j = 1; j <= i; j++) {
                sumS = (long)((j * (j - 1) / 2 + (i - j + 1) * (i - j) / 2) % modVal);
                fArr[i] = (fArr[i] + fArr[j - 1] * fArr[i - j] % modVal * (i + 1) % modVal * CArr[i - 1][j - 1]) % modVal;
                gArr[i] = (gArr[i] + ((gArr[j - 1] * fArr[i - j] + fArr[j - 1] * gArr[i - j]) % modVal * (i + 1) + fArr[j - 1] * fArr[i - j] % modVal * sumS) % modVal * CArr[i - 1][j - 1]) % modVal;
            }
        }

        for (int i = 0; i < 501; i++) {
            for (int j = 0; j < 501; j++) {
                hArr[i][j][0] = 0;
                hArr[i][j][1] = 0;
            }
        }
        hArr[0][0][0] = 1;

        int maxLimit2 = Math.min(mVal, nVal - mVal + 1);
        for (int i = 0; i < maxLimit2; i++) {
            for (int j = 0; j < mVal; j++) {
                for (int k = 1; k <= mVal - j; k++) {
                    tempF = fArr[k] * CArr[j + k][j] % modVal;
                    hArr[i + 1][j + k][0] = (hArr[i + 1][j + k][0] + hArr[i][j][0] * tempF) % modVal;
                    hArr[i + 1][j + k][1] = (hArr[i + 1][j + k][1] + hArr[i][j][1] * tempF) % modVal;
                    hArr[i + 1][j + k][1] = (hArr[i + 1][j + k][1] + hArr[i][j][0] * gArr[k] % modVal * CArr[j + k][j]) % modVal;
                }
            }
        }

        answerVal = 0;
        for (int i = 1; i <= maxLimit2; i++) {
            answerVal = (answerVal + hArr[i][mVal][1] * CArr[nVal - mVal + 1][i]) % modVal;
        }

        System.out.println(answerVal % modVal);
        sc.close();
    }
}
